/** 防止資料變更後，未重核便沿用這次核讀；不是語意審核的替代。 */
export function cardReviewKey(card: Card): string {
  const text = JSON.stringify([card.id, card.system, card.topic, card.kind, card.layer, card.pole ?? null, card.when ?? null, card.none ?? null, card.decades ?? null, card.claim, card.en ?? null, card.limit ?? null, card.sources]);
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) { h ^= text.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16).padStart(8, '0');
}

export type ReviewRecord = { key: string; sources: { id: string; sha256?: string }[] };
export const MING_REVIEWED: Readonly<Record<string, ReviewRecord>> = reviewed.cards;
export function isProseReviewed(card: Card): boolean {
  const review = MING_REVIEWED[card.id];
  return SCHOOL_PROFILE.ref === reviewed.school_profile_ref && card.status !== 'hold' && card.status !== 'needs_atom' && !!review && review.key === cardReviewKey(card);
}
